#include <iostream>
#include <string>

int main()
{
    int sum{ 0 };
    int skipped{ 0 };

    while (true)
    {
        int value{};
        std::cin >> value;
        if (std::cin)
        {
            sum += value;
            continue;
        }
        if (std::cin.eof())
        {
            break;
        }
        std::cin.clear();
        std::string junk{};
        std::cin >> junk;
        ++skipped;
    }

    std::cout << "Sum: " << sum << '\n';
    std::cout << "Skipped: " << skipped << '\n';
    return 0;
}
